values ('ap_calculus_ab', 1, '1.12', array['1.12', '1.16']::text[], 'vocabulary', 'Continuous on an interval', 'A function is continuous on an interval if it is continuous at each point in the interval.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-calculus-ab-reference-u1-u3-2026-10-10; candidate=ap_calculus_ab-u1-r1-016; ced=LIM-2.B.1 A function is continuous on an interval if the function is continuous at each point in the interval.')
