insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_calculus_ab', 1, '1.16', array['1.16']::text[], 'list_sequence', 'Parts of a complete IVT justification', 'A full IVT argument verifies the hypotheses before stating the conclusion.', '[{"label": "Continuity", "meaning": "State that f is continuous on [a, b] and give the reason (e.g. differentiable, so continuous)."}, {"label": "Target value between endpoints", "meaning": "Show with the actual numbers that d lies between f(a) and f(b)."}, {"label": "Conclusion", "meaning": "State that there is at least one c in (a, b) with f(c) = d."}]'::jsonb, NULL, 'Do not state the conclusion without both hypothesis checks. Missing the continuity justification is a common lost point.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-calculus-ab-reference-u1-u3-2026-10-10; candidate=ap_calculus_ab-u1-r1-024; ced=FUN-1.A.1 the Intermediate Value Theorem guarantees that there is at least one number c between a and b, such that f(c) = d; skill 3.C/3.E')
